CREATE TABLE IF NOT EXISTS pairings (code_hash TEXT PRIMARY KEY, device_id TEXT NOT NULL, owner_id TEXT NOT NULL, name TEXT NOT NULL, expires INTEGER NOT NULL, consumed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS devices (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, name TEXT NOT NULL, writer_hash TEXT NOT NULL UNIQUE, viewer_hash TEXT NOT NULL UNIQUE, updated INTEGER NOT NULL DEFAULT 0, paused INTEGER NOT NULL DEFAULT 0, snapshot TEXT, icon_version INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS days (device_id TEXT NOT NULL, day TEXT NOT NULL, snapshot TEXT NOT NULL, PRIMARY KEY (device_id, day), FOREIGN KEY(device_id) REFERENCES devices(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS limits (bucket TEXT PRIMARY KEY, count INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS app_icons (device_id TEXT NOT NULL, package_name TEXT NOT NULL, data TEXT NOT NULL, PRIMARY KEY(device_id, package_name), FOREIGN KEY(device_id) REFERENCES devices(id) ON DELETE CASCADE);
